s-next h4{color:var(--accent)}\n.none{margin:0;color:var(--muted);font-size:12px}\n.ft{display:flex;gap:6px;flex:none}\n.ft .btn{flex:1 1 0;padding:0 6px}\n.note,.err{flex:none;font-size:12px;color:var(--ink);padding:6px 8px;border-radius:8px;border:1px dashed var(--line);background:var(--soft)}\n.fields{flex:1;min-height:0;overflow:auto;display:flex;flex-direction:column;gap:8px}\n.fld{flex:1 0 auto;display:flex;flex-direction:column;gap:3px;min-width:0}\n.fl{font-size:12px;font-weight:700;color:var(--muted)}\n.fld.f-next .fl{color:var(--accent)}\n.ta{display:block;flex:1;width:100%;min-height:58px;padding:7px 9px;border:1px solid var(--line);border-radius:10px;background:var(--paper);color:var(--ink);font:inherit;resize:none}\n.ta::placeholder{color:var(--muted)}\n.ff{flex:none}\n\n.card[data-size=\"3x3\"] .btn{height:30px;font-size:12px}\n.card[data-size=\"3x3\"] .btn.sq{width:28px}\n.card[data-size=\"3x3\"] .btn.sq.sm{width:24px;height:24px}\n.card[data-size=\"3x3\"] .ta{min-height:52px;padding:5px 7px}\n.card[data-size=\"3x3\"] .row{padding:5px 8px}\n.card[data-size=\"3x3\"] .ft .btn{font-size:11.5px}\n\n.card[data-size=\"6x3\"] .pg.home{flex-direction:row;gap:10px}\n.card[data-size=\"6x3\"] .foot{flex-direction:column;justify-content:flex-end;width:112px}\n.card[data-size=\"6x3\"] .foot .btn,.card[data-size=\"6x3\"] .foot .btn.pri{flex:none}\n.card[data-size=\"6x3\"] .pg.form{display:grid;grid-template-columns:minmax(0,1fr) auto;grid-template-rows:auto minmax(0,1fr) auto;gap:6px 8px}\n.card[data-size=\"6x3\"] .fh{grid-column:1;grid-row:1}\n.card[data-size=\"6x3\"] .ff{grid-column:2;grid-row:1}\n.card[data-size=\"6x3\"] .ff .btn{width:auto}\n.card[data-size=\"6x3\"] .fields{grid-column:1/-1;grid-row:2;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));grid-template-rows:minmax(0,1fr);overflow:hidden}\n.card[data-size=\"6x3\"] .fld{flex:none;min-height:0}\n.card[data-size=\"6x3\"] .ta{flex:1;min-height:0;height:100%}\n.card[data-size=\"6x3\"] .err{grid-column:1/-1;grid-row:3;padding:3px 8px}\n.card[data-size=\"6x3\"] .body{flex-direction:row;gap:10px}\n.card[data-size=\"6x3\"] .sec{flex:1 1 0;min-width:0}\n.card[data-size=\"6x3\"] .list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));align-content:start}\n.card[data-size=\"6x3\"] .yr{grid-column:1/-1}\n\n.card[data-size=\"6x6\"] .pg{gap:10px}\n.card[data-size=\"6x6\"] .ta{min-height:80px}\n.card[data-size=\"6x6\"] .focus li{font-size:15px}\n.card[data-size=\"6x6\"] .list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));align-content:start}\n.card[data-size=\"6x6\"] .yr{grid-column:1/-1}\n.card[data-size=\"6x6\"] .rec .list{grid-template-columns:minmax(0,1fr)}\n.card[data-size=\"3x6\"] .ta{min-height:80px}\n";
function pad(n){return n<10?'0'+n:''+n}
function toStr(d){return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())}
function parseDay(s){const p=String(s).split('-');return new Date(+p[0],(+p[1])-1,+p[2])}
function addDays(s,n){const d=parseDay(s);d.setDate(d.getDate()+n);return toStr(d)}
function weekOf(s){const d=parseDay(s);const wd=(d.getDay()+6)%7;d.setDate(d.getDate()-wd);return toStr(d)}
function shortDay(s){const p=s.split('-');return p[1]+'.'+p[2]}
function weekRange(w){return shortDay(w)+'–'+shortDay(addDays(w,6))}
function weekNo(w){
  const th=parseDay(addDays(w,3));
  const j1=new Date(th.getFullYear(),0,1);
  const doy=Math.round((th-j1)/86400000);
  return Math.floor(doy/7)+1;
}
function listOf(s){
  return String(s||'').split('\n').map(function(x){return x.replace(/^\s*[-•·*]\s*/,'').trim()}).filter(Boolean);
}
function reviewsOf(s){
  const a=(s&&Array.isArray(s.reviews))?s.reviews:[];
  return a.slice().sort(function(x,y){return x.week<y.week?1:(x.week>y.week?-1:0)});
}
function allReviews(s){return (s&&Array.isArray(s.reviews))?s.reviews:[]}

function mount(ctx){
  const {root,el,state,ui,commit,redraw,uid,day,size}=ctx;
  const all=reviewsOf(state);
  const thisWeek=weekOf(day());
  const cur=all.find(function(r){return r.week===thisWeek});
  const go=function(patch){Object.assign(ui,patch);redraw();};
  const btn=function(label,onClick,cls,extra){
    return el('button',Object.assign({type:'button',class:'btn '+(cls||''),onclick:onClick},extra||{}),label);
  };
  const openEdit=function(r,from){
    ui.draft=r?{id:r.id,week:r.week,progress:r.progress||'',difficulty:r.difficulty||'',next:r.next||''}
      :{week:thisWeek,progress:'',difficulty:'',next:''};
    go({view:'edit',from:from,err:''});
  };
  const openDetail=function(id){go({view:'detail',sel:id,confirmDel:null});};
  const snippet=function(r){
    const p=listOf(r.progress)[0],q=listOf(r.difficulty)[0],n=listOf(r.next)[0];
    if(p)return '进步 · '+p;
    if(q)return '困难 · '+q;
    if(n)return '调整 · '+n;
    return '';
  };
  const rowOf=function(r){
    return el('button',{type:'button',class:'row',onclick:function(){openDetail(r.id);}},
      el('span',{class:'rt'},el('span',{class:'rg'},weekRange(r.week)),el('span',{class:'wn'},'第'+weekNo(r.week)+'周')),
      el('span',{class:'sn'},snippet(r)));
  };

  function renderHome(){
    const focus=all.find(function(r){return listOf(r.next).length>0});
    const body=focus
      ?el('ul',{class:'focus'},...listOf(focus.next).map(function(t){return el('li',{},t)}))
      :el('p',{class:'empty'},all.length?'最近的复盘里还没写下周要调整的事。':'写下第一次复盘，这里会显示下周重点。');
    const kids=[el('div',{class:'hd'},
      el('span',{class:'tag'},'下周重点'),
      el('span',{class:'chip'+(cur?' ok':'')},cur?'本周已复盘':'本周待复盘'))];
    if(focus)kids.push(el('div',{class:'src'},'来自 '+weekRange(focus.week)+' 复盘'));
    kids.push(el('div',{class:'focusbox'},body));
    if((size==='3x6'||size==='6x6')&&all.length){
      kids.push(el('div',{class:'rec'},el('div',{class:'rtl'},'最近记录'),el('div',{class:'list'},...all.map(function(r){return rowOf(r)}))));
    }
    const foot=el('div',{class:'foot'},
      btn(cur?'编辑本周':'写本周复盘',function(){openEdit(cur||null,'home');},'pri'),
      btn(all.length?'历史 '+all.length:'历史',function(){go({view:'history'});},''));
    return el('div',{class:'pg home'},el('div',{class:'main'},...kids),foot);
  }

  function renderHistory(){
    const kids=[];
    let yr='';
    all.forEach(function(r){
      const y=r.week.slice(0,4);
      if(y!==yr){yr=y;kids.push(el('div',{class:'yr'},y+' 年'));}
      kids.push(rowOf(r));
    });
    const list=all.length?el('div',{class:'list'},...kids):el('p',{class:'empty'},'还没有任何复盘记录。');
    return el('div',{class:'pg hist'},
      el('div',{class:'hdr'},
        btn('‹',function(){go({view:'home'});},'sq',{'aria-label':'返回'}),
        el('span',{class:'ttl'},'历史记录'),
        el('span',{class:'chip'},all.length+' 周')),
      list);
  }


  const SECS=[['progress','这周的进步'],['difficulty','遇到的困难'],['next','下周要调整的事']];

  function renderDetail(){
    const idx=all.findIndex(function(r){return r.id===ui.sel});
    if(idx<0){ui.view='history';return renderHistory();}
    const r=all[idx];
    const older=all[idx+1],newer=all[idx-1];
    const secs=SECS.map(function(pair){
      const items=listOf(r[pair[0]]);
      return el('section',{class:'sec s-'+pair[0]},
        el('h4',{},pair[1]),
        items.length?el('ul',{},...items.map(function(x){return el('li',{},x)})):el('p',{class:'none'},'未填写'));
    });
    const del=ui.confirmDel===r.id;
    let foot;
    if(del){
      foot=el('div',{class:'ft'},
        btn('取消',function(){go({confirmDel:null});},''),
        btn('确认删除',function(){
          commit(function(s){
            return Object.assign({},s,{reviews:allReviews(s).filter(function(x){return x.id!==r.id})});
          },{view:'history',sel:null,confirmDel:null,draft:null,err:'',from:null});
        },'warn'));
    }else{
      foot=el('div',{class:'ft'},
        btn('‹ 较早',function(){if(older)openDetail(older.id);},'',{disabled:!older}),
        btn('较新 ›',function(){if(newer)openDetail(newer.id);},'',{disabled:!newer}),
        btn('删除',function(){go({confirmDel:r.id});},''));
    }
    const kids=[
      el('div',{class:'hdr'},
        btn('‹',function(){go({view:'history',confirmDel:null});},'sq',{'aria-label':'返回历史'}),
        el('span',{class:'ttl'},weekRange(r.week)),
        btn('编辑',function(){openEdit(r,'detail');},'pri sm2')),
      el('div',{class:'meta'},'第'+weekNo(r.week)+'周'+(r.updatedAt?' · 修改于 '+r.updatedAt:'')),
      el('div',{class:'body'},...secs)
    ];
    if(del)kids.push(el('div',{class:'note'},'删除后这一周的记录无法恢复。'));
    kids.push(foot);
    return el('div',{class:'pg detail'},...kids);
  }

  function renderForm(){
    if(!ui.draft)ui.draft={week:thisWeek,progress:'',difficulty:'',next:''};
    const d=ui.draft;
    const editing=!!d.id;
    const shift=function(n){
      const w=addDays(d.week,n*7);
      if(w>thisWeek)return;
      d.week=w;
      go({err:''});
    };
    const back=function(){go({view:ui.from==='detail'?'detail':'home',draft:null,err:''});};
    const hdr=el('div',{class:'hdr fh'},
      btn('‹',back,'sq',{'aria-label':'返回'}),
      editing
        ?el('span',{class:'ttl'},'编辑 '+weekRange(d.week))
        :el('div',{class:'step'},
          btn('‹',function(){shift(-1);},'sq sm',{'aria-label':'上一周'}),
          el('span',{class:'wk'},weekRange(d.week)),
          btn('›',function(){shift(1);},'sq sm',{'aria-label':'下一周',disabled:d.week>=thisWeek})));
    const defs=[
      ['progress','这周的进步','做得好、有推进的事，每行一条'],
      ['difficulty','遇到的困难','卡在哪里、什么在拖慢你'],
      ['next','下周要调整的事','下周准备怎么改，每行一条']
    ];
    const fields=el('div',{class:'fields'},...defs.map(function(f){
      return el('label',{class:'fld f-'+f[0]},
        el('span',{class:'fl'},f[1]),
        el('textarea',{class:'ta',value:d[f[0]],placeholder:f[2],oninput:function(e){d[f[0]]=e.target.value;}}));
    }));
    const save=function(){
      const p=d.progress.trim(),q=d.difficulty.trim(),n=d.next.trim();
      if(!p&&!q&&!n){go({err:'至少填写一项再保存。'});return;}
      if(!d.id&&all.some(function(r){return r.week===d.week})){
        go({err:'这一周已有复盘，请在历史记录里打开并编辑它。'});
        return;
      }
      const id=d.id||uid();
      const rec={id:id,week:d.week,progress:p,difficulty:q,next:n,updatedAt:day()};
      commit(function(s){
        const list=allReviews(s);
        const has=list.some(function(r){return r.id===id});
        return Object.assign({},s,{reviews:has?list.map(function(r){return r.id===id?rec:r}):list.concat([rec])});
      },{view:'detail',sel:id,confirmDel:null,draft:null,err:'',from:null});
    };
    const kids=[hdr,fields];
    if(ui.err)kids.push(el('div',{class:'err',role:'alert'},'提示：'+ui.err));
    kids.push(el('div',{class:'ff'},btn(editing?'保存修改':'保存复盘',save,'pri wide')));
    return el('div',{class:'pg form'},...kids);
  }

  const v=ui.view||'home';
  let page;
  if(v==='history')page=renderHistory();
  else if(v==='detail')page=renderDetail();
  else if(v==='edit')page=renderForm();
  else page=renderHome();
  while(root.firstChild)root.removeChild(root.firstChild);
  root.append(page);
}

